with f as (select p.oid,p.proname,pg_get_functiondef(p.oid) d from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('get_stock_valuation','_process_refund_single_core','apply_stock_count')) select proname,md5(d) as definition_md5,case proname when 'get_stock_valuation' then d like '%auth.uid() IS NULL%' and d like '%STOCK_VALUATION_BRANCH_REQUIRED%' and d like '%can_permission(''inventory.view'')%' and d like '%user_may_access_branch(p_branch_id)%' and d like '%wh.branch_id = p_branch_id%' and d like '%b.branch_id=p_branch_id%' and not has_function_privilege('anon',oid,'EXECUTE') when '_process_refund_single_core' then regexp_count(d,'PREMIER_REFUND_CORE_ABORT')=4 and regexp_count(d,'v_failure := v_res;')=3 and d not like '%RETURN v_res;%' and d like '%WHEN SQLSTATE ''P0001''%' and d like '%BEGIN%BEGIN%UPDATE sale_items%EXCEPTION%RETURN v_failure;%' when 'apply_stock_count' then regexp_count(d,'RAISE EXCEPTION ''STOCK_COUNT_ABORT''')=4 and d like '%FOR UPDATE%' and d like '%ORDER BY id%' and d like '%private.apply_unified_raw_movement_v1%' and d like '%private.remove_product_stock_non_fifo_v1%' and d like '%BEGIN%BEGIN%UPDATE public.stock_counts%EXCEPTION%RETURN v_failure;%' end as p0_structure_pass from f order by proname;
